import time

# Function to generate a random grid
def generate_random_grid(rows, cols):
    grid = [[0 for _ in range(cols)] for _ in range(rows)]
    for row in range(rows):
        for col in range(cols):
            if row % 2 == 0 and col % 2 == 0:
                grid[row][col] = 1
            elif row % 2 != 0 and col % 2 != 0:
                grid[row][col] = 1
    return grid

# Function to simulate a single generation
def simulate_generation(grid):
    new_grid = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]
    for row in range(len(grid)):
        for col in range(len(grid[0])):
            live_neighbors = sum(grid[(row - i) % len(grid)][(col - j) % len(grid[0])] for i in range(-1, 2) for j in range(-1, 2))
            if grid[row][col] == 1:
                new_grid[row][col] = 1 if live_neighbors in (2, 3) else 0
            else:
                new_grid[row][col] = 0 if live_neighbors == 3 else 1
    return new_grid

# Main function to simulate the Game of Life
def simulate_game_of_life(rows, cols, generations):
    grid = generate_random_grid(rows, cols)
    for _ in range(generations):
        print(f"Generation {_ + 1}:")
        for row in grid:
            print(' '.join(str(cell) for cell in row))
